; corners.asm -- chapter 39: the same, walled reading the four corners only
; generated by gen39.py
        INCLUDE "msx.inc"
        OUTPUT "corners.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; Four balls walk a pixel a frame, one towards each wall of the room; before
; each step walled is asked about the next place.
; WALLED HERE: THE FOUR CORNERS ONLY.
stat    EQU VARS                ; the status the interrupt routine read
ticks   EQU VARS + 1            ; frames, two bytes
names   EQU $C400               ; the copy of the 768 names
copy    EQU $C800               ; the copy of the sprites' attributes
ATT_TABLE EQU $1B00
PAT_TABLE EQU $3800
END_MARK EQU $D0                ; a Y of 208 ends the table
balls   EQU VARS + 3            ; four balls, 6 bytes each: X, Y, the steps
                                ; in X and Y, moving, the frame it stopped
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, END_MARK
        out (VDP_DATA), a
        VRAM_WRITE $0000        ; the shapes: all paper ...
        ld bc, 2048
.shp:   xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .shp
        VRAM_WRITE $0008        ; ... but name 1, the brick
        ld hl, brick
        ld bc, (8 << 8) | VDP_DATA
        otir
        VRAM_WRITE $2000        ; the colours: black on white ...
        ld bc, 2048
.col:   ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .col
        VRAM_WRITE $2008        ; ... but the brick's
        ld hl, brick + 8
        ld bc, (8 << 8) | VDP_DATA
        otir
        VRAM_WRITE PAT_TABLE    ; the sprite patterns
        ld hl, patterns
        ld bc, (96 << 8) | VDP_DATA
        otir
        ld hl, room             ; the names, into their copy ...
        ld de, names
        ld bc, 768
        ldir
        VRAM_WRITE $1800        ; ... and from there to the VDP
        ld hl, names
        ld bc, 768
.nam:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .nam
        ld hl, 0
        ld (ticks), hl
        ld a, END_MARK          ; no sprites in the copy yet
        ld (copy), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        ld hl, start            ; the balls
        ld de, balls
        ld bc, 24
        ldir
        call build
        in a, (VDP_CTRL)        ; F cleared: the first interrupt ends a frame
        VDP_REG 1, $E2          ; display on, interrupt on, sprites 16 x 16
        ei
main:   halt                    ; the copy sent, the frame counted
        call move
        call build
        jr main

; isr: every frame. The status kept in stat, the copy of the sprites'
; attributes sent (the paper is over: at full speed, chapter 20), the frame
; counted. Keeps AF, BC, HL
isr:    push af
        push bc
        push hl
        in a, (VDP_CTRL)        ; the status: F, 5S and C; the signal down
        ld (stat), a
        VRAM_WRITE ATT_TABLE
        ld hl, copy
        ld bc, (17 << 8) | VDP_DATA
        otir
        ld hl, (ticks)
        inc hl
        ld (ticks), hl
        pop hl
        pop bc
        pop af
        ei
        ret

; move: each ball still moving a step on, unless walled finds a wall at the
; next place: then it stops, and the frame is kept
move:   ld ix, balls
        ld a, 4
.ball:  push af
        ld a, (ix+4)            ; moving?
        or a
        jr z, .next
        ld a, (ix+0)
        add a, (ix+2)
        ld b, a                 ; B: the next X
        ld a, (ix+1)
        add a, (ix+3)
        ld c, a                 ; C: the next Y
        push bc
        call walled
        pop bc
        jr nz, .stop
        ld (ix+0), b            ; no wall: the ball goes there
        ld (ix+1), c
        jr .next
.stop:  ld (ix+4), 0            ; a wall: it stops where it is
        ld a, (ticks)
        ld (ix+5), a            ; in this frame
.next:  ld de, 6
        add ix, de
        pop af
        dec a
        jr nz, .ball
        ret

; build: the copy of the attributes from the balls: Y, X, pattern 0, black
build:  ld ix, balls
        ld hl, copy
        ld b, 4
.spr:   ld a, (ix+1)
        ld (hl), a
        inc hl
        ld a, (ix+0)
        ld (hl), a
        inc hl
        ld (hl), 0
        inc hl
        ld (hl), BLACK
        inc hl
        ld de, 6
        add ix, de
        djnz .spr
        ld (hl), END_MARK
        ret

; walled: B = X, C = Y of a ball's place -> NZ if a wall is under one of the
; four corners of its box of 16 x 16: the pixels (X, Y + 1), (X + 15, Y + 1),
; (X + 15, Y + 16) and (X, Y + 16). Uses A, BC, DE, HL
walled: inc c                   ;  5  the first line
        call corner             ; 18  top left
        ret nz                  ; 12, or 6
        ld a, b                 ;  5
        add a, 15               ;  8
        ld b, a                 ;  5
        call corner             ; 18  top right
        ret nz                  ; 12, or 6
        ld a, c                 ;  5
        add a, 15               ;  8
        ld c, a                 ;  5
        call corner             ; 18  bottom right
        ret nz                  ; 12, or 6
        ld a, b                 ;  5
        sub 15                  ;  8
        ld b, a                 ;  5  and bottom left, below
; corner: B = X, C = a line -> NZ if the cell that holds the pixel is a wall
corner: call cell               ; 18
        ld a, (hl)              ;  8
        or a                    ;  5
        ret                     ; 11

; cell: B = X, C = a line -> HL: the cell of the copy of the names that holds
; the pixel. Keeps BC. Uses A, DE
cell:   ld a, c                 ;  5
        and $F8                 ;  8  the row x 8
        ld l, a                 ;  5
        ld h, 0                 ;  8
        add hl, hl              ; 12
        add hl, hl              ; 12  the row x 32
        ld a, b                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8  the column
        add a, l                ;  5
        ld l, a                 ;  5
        ld de, names            ; 11
        add hl, de              ; 12
        ret                     ; 11
brick:  db $FF, $80, $80, $80, $FF, $08, $08, $08
        db $14, $14, $14, $14, $14, $14, $14, $14
patterns:                       ; ball 0, face 4, inside of the face 8
        db $00, $07, $0F, $1F, $3F, $7F, $7F, $7F
        db $7F, $7F, $7F, $3F, $1F, $0F, $07, $00
        db $00, $E0, $F0, $F8, $FC, $FE, $FE, $FE
        db $FE, $FE, $FE, $FC, $F8, $F0, $E0, $00
        db $07, $18, $20, $40, $46, $86, $80, $80
        db $80, $88, $47, $40, $20, $18, $07, $00
        db $E0, $18, $04, $02, $62, $61, $01, $01
        db $01, $11, $E2, $02, $04, $18, $E0, $00
        db $00, $07, $1F, $3F, $39, $79, $7F, $7F
        db $7F, $77, $38, $3F, $1F, $07, $00, $00
        db $00, $E0, $F8, $FC, $9C, $9E, $FE, $FE
        db $FE, $EE, $1C, $FC, $F8, $E0, $00, $00
room:                           ; the names: a ring of bricks and a post
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $01, $00, $00, $00, $00, $00, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $00
        db $00, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $00
